parameters.jsCode:
const items = $input.all();
const webhookData = $('Webhook').first().json;

const results = items.map(item => {
  try {
    const content = item.json.choices?.[0]?.message?.content || '{}';
    const parsed = JSON.parse(content);

    return {
      json: {
        success: true,
        data: parsed,
        meta: {
          provider: 'openai',
          model: item.json.model || webhookData.body.model || 'gpt-4o',
          execution_mode: webhookData.body.execution_mode || 'online',
          tokens_used: item.json.usage?.total_tokens || 0
        }
      }
    };
  } catch (e) {
    return {
      json: {
        success: false,
        error: {
          code: 500,
          message: 'Failed to parse quiz response: ' + e.message,
          status: 'INTERNAL_ERROR'
        },
        meta: {
          provider: 'openai',
          execution_mode: webhookData.body.execution_mode || 'online'
        }
      }
    };
  }
});

return results;
